// 🏫 St. Eugene 7 (§24) — what a lesson is made of.
//
// A lesson is a QUEUE OF BLOCKS. Five kinds, and nothing else: something to
// read, something to pick, something to build, something to watch, something
// to play. The lesson engine (`src/logic/steugeneLesson.ts`) shuffles them into
// a run long enough to fill the clock; the player (`src/components/steugene/`)
// draws them.
//
// Every block is DATA. That is the whole reason this file exists: a block
// written by hand in a pack and a block generated by the AI on Dad's say-so
// (§24h) are the same shape, so the player cannot tell them apart and nothing
// downstream has to care.

/** How a mark on a drawing is coloured. */
export type SeTone = 'good' | 'bad' | 'focus' | 'calm'

/**
 * The drawings. Deliberately a small closed set rather than free SVG: he has
 * trouble reading, so almost every block wants a picture, and a picture that
 * takes ten minutes to author never gets authored. These five take one line.
 */
export type SeArt =
  /** A number line. The workhorse — integers, fractions, negatives, distance. */
  | {
      art: 'numberline'
      from: number
      to: number
      /** Gap between labelled ticks. Defaults to 1. */
      step?: number
      points?: { at: number; label?: string; tone?: SeTone }[]
      /** Shade the span between two values — "how far apart", visually. */
      span?: [number, number]
    }
  /** A fraction bar: `filled` of `parts` shaded. */
  | { art: 'bar'; parts: number; filled: number; label?: string; tone?: SeTone }
  /** The same thing as a circle, for when the question is about pizza. */
  | { art: 'pie'; parts: number; filled: number; label?: string; tone?: SeTone }
  /** Integer counters: red minuses and green pluses, cancelling in pairs. */
  | { art: 'counters'; pos: number; neg: number; cancel?: boolean }
  /** A balance scale — the picture that makes "do it to both sides" obvious. */
  | { art: 'scale'; left: string; right: string; tilt?: -1 | 0 | 1 }
  /** Proportional bars, for comparing quantities without a chart library. */
  | { art: 'bars'; rows: { label: string; value: number; tone?: SeTone }[]; unit?: string }

/** A callout inside an explanation. Four flavours, same as the Academy's. */
export interface SeCallout {
  flavour: 'imagine' | 'gotcha' | 'key' | 'pirate'
  text: string
}

/**
 * One step of a worked solution, shown after a WRONG answer.
 *
 * §24f: the walk-through never uses the numbers he just got wrong. He does not
 * get to fix that question, so showing him its answer teaches him to copy;
 * showing him the same move on a different number teaches him the move.
 */
export interface SeStep {
  text: string
  art?: SeArt
}

interface SeBlockBase {
  id: string
  /** Rough seconds, used only to size the opening queue. Never shown to him. */
  secs?: number
}

/** Something to read. Short lines — never a paragraph. */
export interface SeExplain extends SeBlockBase {
  kind: 'explain'
  title: string
  emoji?: string
  /** One idea per line. The reader reads them one at a time. */
  lines: string[]
  art?: SeArt
  callout?: SeCallout
}

/** Multiple choice. Three options (§24f), one right. */
export interface SeChoice extends SeBlockBase {
  kind: 'choice'
  prompt: string
  art?: SeArt
  options: string[]
  /** Index into `options`. */
  answer: number
  /** Said out loud whichever way it goes — the fact, not the verdict. */
  why: string
  /** The didactic walk-through, on a DIFFERENT number. */
  steps?: SeStep[]
}

/**
 * He types it himself — but out of a hand of tiles that already contains every
 * character of the answer, plus decoys (§24f). Reading is the hard part for
 * him; the maths is not, and a blank keyboard tests the wrong thing.
 */
export interface SeBuild extends SeBlockBase {
  kind: 'build'
  prompt: string
  art?: SeArt
  /** Exactly what the tiles must spell, e.g. "-12" or "3/4" or "1.0". */
  answer: string
  /** Decoy tiles. Authored where a good decoy matters; otherwise generated. */
  decoys?: string[]
  why: string
  steps?: SeStep[]
}

/**
 * A video he cannot escape from (§24g): a no-cookie embed with no related
 * videos, no channel link and a shield over the chrome. `checks` are asked
 * AFTER it finishes, which is the entire reason the video is here.
 */
export interface SeVideo extends SeBlockBase {
  kind: 'video'
  youtube: string
  title: string
  /** Who made it — credited on the card, not linked. */
  by?: string
  /** Runtime, for the queue estimate. */
  seconds: number
  /** Start/stop inside a longer video, so a 20-minute upload can give 3 minutes. */
  start?: number
  end?: number
  checks: Omit<SeChoice, 'kind' | 'id'>[]
}

/** The minigames. Three shapes, every one of them tap-only (no dragging). */
export interface SeGame extends SeBlockBase {
  kind: 'game'
  title: string
  /** Order the values smallest → largest by tapping them in sequence. */
  game:
    | { mode: 'order'; values: { label: string; value: number }[] }
    /** Tap a left card, then its partner on the right. */
    | { mode: 'pair'; pairs: [string, string][] }
    /** Tap the spot on a number line where the value lives. */
    | { mode: 'line'; from: number; to: number; step: number; targets: { label: string; at: number }[] }
  why?: string
}

export type SeBlock = SeExplain | SeChoice | SeBuild | SeVideo | SeGame

/**
 * Everything written for one subtopic.
 *
 * `core` is the spine — what he gets the first time, in this order. `extra` is
 * the deep bench: the engine splices from it whenever he is working faster than
 * the clock (§24d), and draws the whole lesson from it when he repeats a
 * subtopic, so a repeat is never the same lesson twice.
 */
export interface SePack {
  subtopicId: string
  core: SeBlock[]
  extra: SeBlock[]
}

// --- The AI desk (§24h) ------------------------------------------------------
//
// He can ask for more. He cannot help himself to more. Every request is a row
// in `app/steugene` that Dad has to approve, and only then does anything get
// generated — with Dad's key, on Dad's device. That is the whole mechanism,
// and it exists because an "unlimited explanations" button pointed at a paid
// API is a bill waiting to happen.

export interface SeAiRequest {
  id: string
  subtopicId: string
  /** A nicety for the notification — "Rational numbers", not "math-rational". */
  subtopicTitle: string
  want: 'questions' | 'explain'
  at: number
  status: 'pending' | 'approved' | 'denied' | 'failed'
  decidedAt?: number
  /** How many blocks actually landed. */
  made?: number
  /** Verbatim, when it failed. A vague reason is worse than a long one. */
  error?: string
  /** He has seen the verdict. */
  seen?: boolean
}

/** One approved batch, appended to the subtopic's bench. */
export interface SeGenerated {
  id: string
  subtopicId: string
  at: number
  blocks: SeBlock[]
}

export interface SeDesk {
  requests: SeAiRequest[]
  generated: SeGenerated[]
}
